import Vue from 'vue'
import VueRouter from 'vue-router'
import DashboardContent from '../views/Dashboard.vue'
import MainLayout from '../layouts/MainLayout.vue'
import PlayerList from '../views/players/PlayerList.vue'
import BanList from '../views/players/BanList.vue'
import ServerList from '../views/servers/ServerList.vue'
import ServerSettings from '../views/servers/ServerSettings.vue'
import SaveManager from '../views/servers/SaveManager.vue'
import ModList from '../views/mods/ModList.vue'
import ModSettings from '../views/mods/ModSettings.vue'
import ItemList from '../views/items/ItemList.vue'
import ItemGenerator from '../views/items/ItemGenerator.vue'
import Announcements from '../views/Announcements.vue'
import SystemSettings from '../views/SystemSettings.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    component: MainLayout,
    children: [
      {
        path: '',
        name: 'Dashboard',
        component: DashboardContent,
        meta: { title: '控制面板' }
      },
      {
        path: 'players/list',
        name: 'PlayerList',
        component: PlayerList,
        meta: { title: '玩家列表' }
      },
      {
        path: 'players/ban',
        name: 'BanList',
        component: BanList,
        meta: { title: '封禁管理' }
      },
      {
        path: 'servers/list',
        name: 'ServerList',
        component: ServerList,
        meta: { title: '服务器列表' }
      },
      {
        path: 'servers/settings',
        name: 'ServerSettings',
        component: ServerSettings,
        meta: { title: '服务器设置' }
      },
      {
        path: 'servers/saves',
        name: 'SaveManager',
        component: SaveManager,
        meta: { title: '存档管理' }
      },
      {
        path: 'mods/list',
        name: 'ModList',
        component: ModList,
        meta: { title: '已安装模组' }
      },
      {
        path: 'mods/settings',
        name: 'ModSettings',
        component: ModSettings,
        meta: { title: '模组设置' }
      },
      {
        path: 'items/list',
        name: 'ItemList',
        component: ItemList,
        meta: { title: '物品列表' }
      },
      {
        path: 'items/generate',
        name: 'ItemGenerator',
        component: ItemGenerator,
        meta: { title: '物品生成' }
      },
      {
        path: 'announcements',
        name: 'Announcements',
        component: Announcements,
        meta: { title: '公告管理' }
      },
      {
        path: 'settings',
        name: 'SystemSettings',
        component: SystemSettings,
        meta: { title: '系统设置' }
      }
    ]
  }
]

const router = new VueRouter({
  routes
})

router.beforeEach((to, from, next) => {
  document.title = `饥荒管理系统 - ${to.meta.title || ''}`
  next()
})

export default router
